// Purchasing exceptions for the Ops Hub, from Fulfil PROD (read-only feed).
// Two reports from two reads, so a reader of the hub sees the same rows the Monday email sends:
//   po-past-etd    tabs 'past'  = open PO whose delivery_date has gone by
//                       'noetd' = open PO with no delivery_date on file at all (it can never go past)
//   po-no-invoice  tab  'main'  = goods received, invoice still none/waiting
// Emits ONE item: { ok, tabs, runStartedAt, checkedAtIso, records[], summaries[], feed{} }.
// ok=false when either read failed: nothing is upserted or auto-cleared then, so a bad run
// leaves yesterday's good rows in place rather than blanking the report.
const BASE = 'https://dockandbay.fulfil.io/client/#/model/';
const runStartedAt = $('Run config').first().json.runStartedAt;
const now = new Date();
const checkedAtIso = now.toISOString();
const checkedAt = checkedAtIso.slice(0, 16).replace('T', ' ') + ' UTC';
const today = checkedAtIso.slice(0, 10);

function rows(name) {
  try { return $(name).all().map(i => i.json).filter(j => j && j.id != null); } catch (e) { return null; }
}
const open = rows('Fulfil open purchase orders');
const noinv = rows('Fulfil POs received not invoiced');
// An empty not-invoiced list is a legitimate result (nothing outstanding); an empty open-PO list is not.
const ok = !!(open && open.length && noinv);

const iso = d => (d && typeof d === 'object') ? String(d.iso_string || '').slice(0, 10) : String(d || '').slice(0, 10);
const dayDiff = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 86400000);
const txt = v => (v === null || v === undefined || v === '') ? null : String(v);

const records = [];
const counts = { past: {rows:0, breach:0, dropship:0}, noetd: {rows:0, breach:0, dropship:0}, main: {rows:0, breach:0, dropship:0} };

function push(reportId, tab, ref, payload, severity, why) {
  records.push({ report_id: reportId, tab, ref, payload, severity, severity_why: why, updated_at: runStartedAt });
  counts[tab].rows += 1;
}

// ---- po-past-etd -----------------------------------------------------------
for (const p of (open || [])) {
  const etd = iso(p.delivery_date);
  const raised = iso(p.purchase_date);
  const age = raised ? dayDiff(today, raised) : null;
  const late = etd ? dayDiff(today, etd) : null;
  const tab = etd ? (late > 0 ? 'past' : null) : 'noetd';
  if (!tab) continue;                                   // due in future, not an exception
  const payload = {
    po: p.number, link: BASE + 'purchase.purchase/' + p.id,
    reference: txt(p.reference),                        // Ben 12 Oct: the reference is what Ops recognises
    supplier: txt(p['party.rec_name']),
    company: txt(p['company.rec_name']),
    etd: etd || null, lateDays: late, raised: raised || null, ageDays: age,
    requested: iso(p.requested_shipping_date) || null,
    state: p.state, goods: p.shipment_state, invoice: p.invoice_state,
  };
  if (tab === 'past') {
    const s = Math.min(99, 50 + Math.max(0, late));
    counts.past.breach += late >= 30 ? 1 : 0;
    push('po-past-etd', 'past', p.number, payload, s, late + 'd past the delivery date on the PO');
  } else {
    const s = age === null ? null : Math.min(80, 30 + Math.round(age / 7));
    push('po-past-etd', 'noetd', p.number, payload, s,
         'no delivery date on file' + (age === null ? '' : ', raised ' + age + 'd ago'));
  }
}

// ---- po-no-invoice ---------------------------------------------------------
for (const p of (noinv || [])) {
  const raised = iso(p.purchase_date);
  const age = raised ? dayDiff(today, raised) : null;
  const payload = {
    po: p.number, link: BASE + 'purchase.purchase/' + p.id,
    reference: txt(p.reference),
    supplier: txt(p['party.rec_name']),
    company: txt(p['company.rec_name']),
    raised: raised || null, ageDays: age,
    invoice: p.invoice_state, goods: p.shipment_state, state: p.state,
  };
  const s = age === null ? null : Math.min(99, 45 + Math.round(age / 3));
  if (age !== null && age >= 60) counts.main.breach += 1;
  push('po-no-invoice', 'main', p.number, payload, s,
       'goods received, invoice ' + p.invoice_state + (age === null ? '' : ', raised ' + age + 'd ago'));
}

const sources = [
  { source: 'Fulfil: open purchase orders',      status: open  && open.length ? 'OK' : 'FAILED', rows: open  ? open.length  : 0 },
  { source: 'Fulfil: POs received not invoiced', status: noinv ? 'OK' : 'FAILED',                rows: noinv ? noinv.length : 0 },
];
const common = { source: 'Fulfil PROD', ok, checkedAt, checkedAtIso, sources,
                 workflowId: $workflow.id, executionId: $execution.id, runStartedAt };
const summaries = [
  { report_id: 'po-past-etd',   tab: 'past',  checked_at: checkedAtIso, payload: Object.assign({ kind: 'purchasing', counts: counts.past  }, common) },
  { report_id: 'po-past-etd',   tab: 'noetd', checked_at: checkedAtIso, payload: Object.assign({ kind: 'purchasing', counts: counts.noetd }, common) },
  { report_id: 'po-no-invoice', tab: 'main',  checked_at: checkedAtIso, payload: Object.assign({ kind: 'purchasing', counts: counts.main  }, common) },
];
const feed = { report: 'Purchasing (Fulfil)', workbook: 'n8n ' + $workflow.id, schedule: 'hourly',
               last_run: checkedAt, result: ok ? 'ok' : 'error',
               duration_ms: Math.max(0, now - Date.parse(runStartedAt)) || null, checked_at: checkedAtIso };

return [{ json: { ok, report_ids: ['po-past-etd', 'po-no-invoice'], tabs: ['past', 'noetd', 'main'],
                  runStartedAt, checkedAtIso, records, summaries, feed, counts, total: records.length } }];

